cter-inventory' and parent_id='chr_800d3e58b5b497357fe501c441398697' and entity_id='inv_92ede3fc7cc4ac9f782ccb4429214a10';
if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_800d3e58b5b497357fe501c441398697' and entity_id='inv_9f3baadabc00ce5701102acfda177ede' and md5(to_jsonb(t)::text)='dbe8403b033fe9d1a529fe73c8416b80')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_9f3baadabc00ce5701102acfda177ede';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_dd56e0a78c09c5ba$"Objeto · Precio base · Peso\nÚtiles de herborista · 5 po · 3 lb\n\nÚtiles de herborista. Este conjunto de objetos incluye una gran variedad de herramientas utilizadas por los herboristas para crear remedios y pociones, como pueden ser unas cizallas, un mortero, bolsas y viales. La competencia con estos útiles te permite sumar tu bonificador por competencia a las pruebas de característica que hagas para identificar o aplicar hierbas. Además, se necesita competencia con estos útiles para elaborar antitoxinas y pociones de curación.\n\nLas herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_dd56e0a78c09c5ba$::jsonb,true),'{features}',$text_61e38f752e2d89de$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Útiles de herborista. Este conjunto de objetos incluye una gran variedad de herramientas utilizadas por los herboristas para crear remedios y pociones, como pueden ser unas cizallas, un mortero, bolsas y viales. La competencia con estos útiles te permite sumar tu bonificador por competencia a las pruebas de característica que hagas para identificar o aplicar hierbas. Además, se necesita competencia con estos útiles para elaborar antitoxinas y pociones de curación.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_61e38f752e2d89de$::jsonb,true),'{rules,definition,description}',$text_60ab5a3c8c12bf60$[{"id":"official-table","rows":[["Útiles de herborista","5 po","3 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Útiles de herborista. Este conjunto de objetos incluye una gran variedad de herramientas utilizadas por los herboristas para crear remedios y pociones, como pueden ser unas cizallas, un mortero, bolsas y viales. La competencia con estos útiles te permite sumar tu bonificador por competencia a las pruebas de característica que hagas para identificar o aplicar hierbas. Además, se necesita competencia con estos útiles para elaborar antitoxinas y pociones de curación.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"tools-context-general","text":"Las herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-tools-context"],"provenance":"official-spanish"}]$text_60ab5a3c8c12bf60$::jsonb,true),'{catalog,revision}',$text_4b227777d4dd1fc6$4$text_4b227777d4dd1fc6$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_ee76d66ef5f1117d$["official-table","official-rules-0","tools-context-general"]$text_ee76d66ef5f1117d$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_800d3e58b5b497357fe501c441398697' and entity_id='inv_9f3baadabc00ce5701102acfda177ede';
