er-inventory' and parent_id='chr_800d3e58b5b497357fe501c441398697' and entity_id='inv_c664a98343943f39345e361802f02398';
if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_800d3e58b5b497357fe501c441398697' and entity_id='inv_d46c2e37cebea72be9f629cd15137673' and md5(to_jsonb(t)::text)='94b2397c762948d5d45110f337cd71e6')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_d46c2e37cebea72be9f629cd15137673';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_29de674beabfb97f$"Objeto · Precio base · Peso\nFuego de alquimista (frasco) · 50 po · 1 lb\n\nFuego de alquimista. Este fluido pegajoso y adherente prende al entrar en contacto con el aire. Como acción, puedes lanzar este frasco hasta a 6 m, lo que hará que se rompa con el impacto. Haz un ataque a distancia contra una criatura u objeto y trata el fuego de alquimista como un arma improvisada. Si impacta, el objetivo sufre 1d4 de daño de fuego al principio de cada uno de sus turnos. Una criatura puede poner fin a este efecto si usa su acción para realizar una prueba de Destreza con CD 10 para extinguir las llamas.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_29de674beabfb97f$::jsonb,true),'{features}',$text_e827c91874ef8602$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Fuego de alquimista. Este fluido pegajoso y adherente prende al entrar en contacto con el aire. Como acción, puedes lanzar este frasco hasta a 6 m, lo que hará que se rompa con el impacto. Haz un ataque a distancia contra una criatura u objeto y trata el fuego de alquimista como un arma improvisada. Si impacta, el objetivo sufre 1d4 de daño de fuego al principio de cada uno de sus turnos. Una criatura puede poner fin a este efecto si usa su acción para realizar una prueba de Destreza con CD 10 para extinguir las llamas.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_e827c91874ef8602$::jsonb,true),'{rules,definition,description}',$text_fc80bfec3e404bfa$[{"id":"official-table","rows":[["Fuego de alquimista (frasco)","50 po","1 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Fuego de alquimista. Este fluido pegajoso y adherente prende al entrar en contacto con el aire. Como acción, puedes lanzar este frasco hasta a 6 m, lo que hará que se rompa con el impacto. Haz un ataque a distancia contra una criatura u objeto y trata el fuego de alquimista como un arma improvisada. Si impacta, el objetivo sufre 1d4 de daño de fuego al principio de cada uno de sus turnos. Una criatura puede poner fin a este efecto si usa su acción para realizar una prueba de Destreza con CD 10 para extinguir las llamas.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_fc80bfec3e404bfa$::jsonb,true),'{catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_times