if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_9a5d864abfda580db6a8b26bcd25282a' and entity_id='inv_180e5bbb51570469f30e9ace730dd92a' and md5(to_jsonb(t)::text)='d246830bbc3f1df2f973085868a9510e')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_180e5bbb51570469f30e9ace730dd92a';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_038a74766038eaf3$"Pequeño fragmento de cristal translúcido, similar al hielo claro, que pulsa con una luz interna tenue y constante. Son restos del banco energético del Corazón, un artefacto aeloriano que alimentaba el templo y sus mecanismos internos.\n\nMecánica\nUsar: acción. El fragmento se consume.\n\nEfecto (elige uno)\n• Recarga menor: restaura una ranura de conjuro de 1.er nivel (no rituales).\n• Pulso vital: otorga 2d6 puntos de golpe temporales a una criatura y cura 1d4 adicionales si se usa dentro del templo.\n\nCorruptibilidad\n• +1 MC si se activa tras derramar sangre o si se consumen varios fragmentos en una misma escena.\n\nIdentificación\nArcana CD 12 o Identificar.\n\nDestrucción\nAplastarlo (Fuerza CD 10) libera un pulso de 1d6 de daño radiante en un cono de 3 m, sin dañar objetos mágicos.\n\nUso en puzzles o artefactos\nTres fragmentos insertados en receptáculos del Corazón activan mecanismos menores como puertas, puentes o plataformas antiguas."$text_038a74766038eaf3$::jsonb,true),'{features}',$text_3e786f0a1bd7f240$[{"id":"consume-crystal","kind":"other","name":"Consumir cristal: elegir un efecto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Pequeño fragmento de cristal translúcido, similar al hielo claro, que pulsa con una luz interna tenue y constante. Son restos del banco energético del Corazón, un artefacto aeloriano que alimentaba el templo y sus mecanismos internos.\n\nMecánica\nUsar: acción. El fragmento se consume.\n\nEfecto (elige uno)\n• Recarga menor: restaura una ranura de conjuro de 1.er nivel (no rituales).\n• Pulso vital: otorga 2d6 puntos de golpe temporales a una criatura y cura 1d4 adicionales si se usa dentro del templo.\n\nCorruptibilidad\n• +1 MC si se activa tras derramar sangre o si se consumen varios fragmentos en una misma escena.\n\nIdentificación\nArcana CD 12 o Identificar.\n\nDestrucción\nAplastarlo (Fuerza CD 10) libera un pulso de 1d6 de daño radiante en un cono de 3 m, sin dañar objetos mágicos.\n\nUso en puzzles o artefactos\nTres fragmentos insertados en receptáculos del Corazón activan mecanismos menores como puertas, puentes o plataformas antiguas.\n\nElegir recuperación de espacio de nivel 1 o 2d6 PG temporales (con 1d4 de curación solo en el templo). No aplicar ambas opciones. Conservar corrupción, destrucción y uso de tres fragmentos en mecanismos.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_3e786f0a1bd7f240$::jsonb,true),'{rules,definition,description}',$text_0cd83eeefae6555b$[{"id":"campaign-text-0","text":"Pequeño fragmento de cristal translúcido, similar al hielo claro, que pulsa con una luz interna tenue y constante. Son restos del banco energético del Corazón, un artefacto aeloriano que alimentaba el templo y sus mecanismos internos.\n\nMecánica\nUsar: acción. El fragmento se consume.\n\nEfecto (elige uno)\n• Recarga menor: restaura una ranura de conjuro de 1.er nivel (no rituales).\n• Pulso vital: otorga 2d6 puntos de golpe temporales a una criatura y cura 1d4 adicionales si se usa dentro del templo.\n\nCorruptibilidad\n• +1 MC si se activa tras derramar sangre o si se consumen varios fragmentos en una misma escena.\n\nIdentificación\nArcana CD 12 o Identificar.\n\nDestrucción\nAplastarlo (Fuerza CD 10) libera un pulso de 1d6 de daño radiante en un cono de 3 m, sin dañar objetos mágicos.\n\nUso en puzzles o artefactos\nTres fragmentos insertados en receptáculos del Corazón activan mecanismos menores como puertas, puentes o plataformas antiguas.","type":"paragraph","section":"rules","sourceIds":["ece-authored-rule"],"provenance":"campaign"}]$text_0cd83eeefae6555b$::jsonb,true),'{rules,personalDescription}',$text_a7dfd88bd47b9ed4$"Pequeño fragmento de cristal translúcido, similar al hielo claro, que pulsa con una luz interna tenue y constante. Son restos del banco energético del Corazón, un artefacto aeloriano que alimentaba el templo y sus mecanismos internos.\n\n<strong>Mecánica</strong>\n<strong>Usar:</strong> acción. El fragmento se consume.\n\n<strong>Efecto (elige uno)</strong>\n• <strong>Recarga menor:</strong> restaura una ranura de conjuro de <u>1.er nivel</u> (no rituales).\n• <strong>Pulso vital:</strong> otorga <u>2d6</u> puntos de golpe temporales a una criatura y cura <u>1d4</u> adicionales si se usa dentro del templo.\n\n<strong>Corruptibilidad</strong>\n• <u>+1 MC</u> si se activa tras derramar sangre o si se consumen varios fragmentos en una misma escena.\n\n<strong>Identificación</strong>\n<em>Arcana CD 12</em> o <em>Identificar</em>.\n\n<strong>Destrucción</strong>\nAplastarlo (<em>Fuerza CD 10</em>) libera un pulso de <u>1d6</u> de daño radiante en un cono de 3 m, sin dañar objetos mágicos.\n\n<strong>Uso en puzzles o artefactos</strong>\nTres fragmentos insertados en receptáculos del Corazón activan mecanismos menores como puertas, puentes o plataformas antiguas."$text_a7dfd88bd47b9ed4$::jsonb,true),'{catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_fc5f9352c74f6058$["campaign-text-0"]$text_fc5f9352c74f6058$::jsonb?id),jsonb_build_array('campaign-text-0')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_9a5d864abfda580db6a8b26bcd25282a' and entity_id='inv_180e5bbb51570469f30e9ace730dd92a';
