d='chr_9a5d864abfda580db6a8b26bcd25282a' and entity_id='inv_3edea96b9705e16b88c0311a51cf76aa';
if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_9a5d864abfda580db6a8b26bcd25282a' and entity_id='inv_88f24da7c256ca8d2ad6f316d64a0694' and md5(to_jsonb(t)::text)='4391dc0561faebc458bb9d3344be6d21')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_88f24da7c256ca8d2ad6f316d64a0694';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(payload,'{rules,personalDescription}',$text_53221947b83782f3$"Esta capa está tejida con hilos oscuros y resistentes, en cuyo forro interior se inscriben antiguas runas arcanas apenas visibles cuando la tela descansa. \n Al portarla, el usuario siente un leve pulso mágico, como si la prenda almacenara fragmentos de energía latente. \n Mientras se viste esta capa, el portador obtiene una ranura adicional de conjuro de nivel 1."$text_53221947b83782f3$::jsonb,true),'{catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_9a5d864abfda580db6a8b26bcd25282a' and entity_id='inv_88f24da7c256ca8d2ad6f316d64a0694';
if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_9a5d864abfda580db6a8b26bcd25282a' and entity_id='inv_8be5a4fb130d90fb69039466952763b5' and md5(to_jsonb(t)::text)='8d863dd4afe260e52c8d5a9bd6e44539')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_8be5a4fb130d90fb69039466952763b5';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_ca5e6004250fdca5$"Objeto · Precio base · Peso\nLibro de conjuros · 50 po · 3 lb\n\nLibro de conjuros. Indispensable para los magos, un libro de conjuros es un tomo encuadernado en cuero con 100 páginas de vitela en blanco, adecuadas para escribir conjuros.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_ca5e6004250fdca5$::jsonb,true),'{features}',$text_aa29c45791edda23$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Libro de conjuros. Indispensable para los magos, un libro de conjuros es un tomo encuadernado en cuero con 100 páginas de vitela en blanco, adecuadas para escribir conjuros.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_aa29c45791edda23$::jsonb,true),'{rules,definition,description}',$text_d0cdc14ec2a16eb6$[{"id":"official-table","rows":[["Libro de conjuros","50 po","3 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":