if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_9a5d864abfda580db6a8b26bcd25282a' and entity_id='inv_a09f925715561140feb221d05f6bd1d9' and md5(to_jsonb(t)::text)='5f8e0c99f10f393484ca4f0030e91586')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_a09f925715561140feb221d05f6bd1d9';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_710aa5ba9966d542$"Objeto · Precio base · Peso\nRopas comunes · 5 pp · 3 lb\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_710aa5ba9966d542$::jsonb,true),'{rules,definition,description}',$text_8b249a8c7a296f12$[{"id":"official-table","rows":[["Ropas comunes","5 pp","3 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$text_8b249a8c7a296f12$::jsonb,true),'{catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_b507874e9dab9bc1$["official-table"]$text_b507874e9dab9bc1$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_9a5d864abfda580db6a8b26bcd25282a' and entity_id='inv_a09f925715561140feb221d05f6bd1d9';
if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_9a5d864abfda580db6a8b26bcd25282a' and entity_id='inv_a2fda2e808a1b2d6a9723afb7372b2e7' and md5(to_jsonb(t)::text)='969def0eb370dc7515c2747018ca9890')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_a2fda2e808a1b2d6a9723afb7372b2e7';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_e09c41a0993ee9c2$"Una capa elegante y sorprendentemente liviana, tejida con hilos que parecen captar la luz y devolverla como un brillo sutil en el borde de la tela. Cuando se la lleva puesta, su caída y su presencia amplifican la intención del portador: cada palabra suena un poco más convincente, cada gesto un poco más seguro.\n\nEfecto\nMientras estés vinculado a esta capa, tu puntuación de Carisma aumenta en +1, hasta un máximo de 20.\n\nImpacto en conjuros\nEste aumento de Carisma también mejora tu CD de salvación de conjuros y tus tiradas de ataque de conjuro si tu clase lanza conjuros usando Carisma.\n\nEncaja especialmente con: pactos feéricos, seducción, dominio social y manipulación sutil."$text_e09c41a0993ee9c2$::jsonb,true),'{features}',$text_7b0c35e6dee571ba$[{"id":"legacy-bonus-0","kind":"passive","name":"CHA","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Carisma +1 (máx. 20).","showInActions":false},{"id":"charisma-bonus","kind":"passive","name":"Carisma +1","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Una capa elegante y sorprendentemente liviana, tejida con hilos que parecen captar la luz y devolverla como un brillo sutil en el borde de la tela. Cuando se la lleva puesta, su caída y su presencia amplifican la intención del portador: cada palabra suena un poco más convincente, cada gesto un poco más seguro.\n\nEfecto\nMientras estés vinculado a esta capa, tu puntuación de Carisma aumenta en +1, hasta un máximo de 20.\n\nImpacto en conjuros\nEste aumento de Carisma también mejora tu CD de salvación de conjuros y tus tiradas de ataque de conjuro si tu clase lanza conjuros usando Carisma.\n\nEncaja especialmente con: pactos feéricos, seducción, dominio social y manipulación sutil.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_7b0c35e6dee571ba$::jsonb,true),'{rules,definition,description}',$text_a2bf17b2daf6b053$[{"id":"campaign-text-0","text":"Una capa elegante y sorprendentemente liviana, tejida con hilos que parecen captar la luz y devolverla como un brillo sutil en el borde de la tela. Cuando se la lleva puesta, su caída y su presencia amplifican la intención del portador: cada palabra suena un poco más convincente, cada gesto un poco más seguro.\n\nEfecto\nMientras estés vinculado a esta capa, tu puntuación de Carisma aumenta en +1, hasta un máximo de 20.\n\nImpacto en conjuros\nEste aumento de Carisma también mejora tu CD de salvación de conjuros y tus tiradas de ataque de conjuro si tu clase lanza conjuros usando Carisma.\n\nEncaja especialmente con: pactos feéricos, seducción, dominio social y manipulación sutil.","type":"paragraph","section":"rules","sourceIds":["ece-authored-rule"],"provenance":"campaign"}]$text_a2bf17b2daf6b053$::jsonb,true),'{rules,personalDescription}',$text_e72aac44c161504a$"Una capa elegante y sorprendentemente liviana, tejida con hilos que parecen captar la luz y devolverla como un brillo sutil en el borde de la tela. Cuando se la lleva puesta, su caída y su presencia amplifican la intención del portador: cada palabra suena un poco más convincente, cada gesto un poco más seguro.\n\n<strong>Efecto</strong>\nMientras estés vinculado a esta capa, tu puntuación de <strong>Carisma</strong> aumenta en <strong>+1</strong>, hasta un máximo de <strong>20</strong>.\n\n<strong>Impacto en conjuros</strong>\nEste aumento de Carisma también mejora tu <em>CD de salvación de conjuros</em> y tus <em>tiradas de ataque de conjuro</em> si tu clase lanza conjuros usando Carisma.\n\n<em>Encaja especialmente con:</em> pactos feéricos, seducción, dominio social y manipulación sutil."$text_e72aac44c161504a$::jsonb,true),'{catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_fc5f9352c74f6058$["campaign-text-0"]$text_fc5f9352c74f6058$::jsonb?id),jsonb_build_array('campaign-text-0')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_9a5d864abfda580db6a8b26bcd25282a' and entity_id='inv_a2fda2e808a1b2d6a9723afb7372b2e7';
if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_9a5d864abfda580db6a8b26bcd25282a' and entity_id='inv_abcec5552b1d22eca585a6948f9a5fce' and md5(to_jsonb(t)::text)='215bedcf76dfb17e3a6b30ff57bcf023')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_abcec5552b1d22eca585a6948f9a5fce';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_08989937f975ed3b$"Objeto · Precio base · Peso\nOrbe · 20 po · 3 lb\n\nCanalizador arcano. Un canalizador arcano es un objeto especial, diseñado para conducir el poder de los conjuros arcanos. Puede ser un orbe, un cristal, un cetro, un bastón fabricado específicamente con este fin, un trozo de madera con forma de varita o un objeto similar. Los brujos, hechiceros y magos pueden utilizar este objeto como canalizador mágico.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_08989937f975ed3b$::jsonb,true),'{features}',$text_7f0fd4e9063deb6a$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Canalizador arcano. Un canalizador arcano es un objeto especial, diseñado para conducir el poder de los conjuros arcanos. Puede ser un orbe, un cristal, un cetro, un bastón fabricado específicamente con este fin, un trozo de madera con forma de varita o un objeto similar. Los brujos, hechiceros y magos pueden utilizar este objeto como canalizador mágico.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_7f0fd4e9063deb6a$::jsonb,true),'{rules,definition,description}',$text_528ba96b62b1dcb8$[{"id":"official-table","rows":[["Orbe","20 po","3 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Canalizador arcano. Un canalizador arcano es un objeto especial, diseñado para conducir el poder de los conjuros arcanos. Puede ser un orbe, un cristal, un cetro, un bastón fabricado específicamente con este fin, un trozo de madera con forma de varita o un objeto similar. Los brujos, hechiceros y magos pueden utilizar este objeto como canalizador mágico.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_528ba96b62b1dcb8$::jsonb,true),'{catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_9a5d864abfda580db6a8b26bcd25282a' and entity_id='inv_abcec5552b1d22eca585a6948f9a5fce';
if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_9a5d864abfda580db6a8b26bcd25282a' and entity_id='inv_bdf552de3729a268a174a3df143ae4f0' and md5(to_jsonb(t)::text)='6a28ef12df9f5a55b681c4ea821b6e3f')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_bdf552de3729a268a174a3df143ae4f0';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_dd56e0a78c09c5ba$"Objeto · Precio base · Peso\nÚtiles de herborista · 5 po · 3 lb\n\nÚtiles de herborista. Este conjunto de objetos incluye una gran variedad de herramientas utilizadas por los herboristas para crear remedios y pociones, como pueden ser unas cizallas, un mortero, bolsas y viales. La competencia con estos útiles te permite sumar tu bonificador por competencia a las pruebas de característica que hagas para identificar o aplicar hierbas. Además, se necesita competencia con estos útiles para elaborar antitoxinas y pociones de curación.\n\nLas herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_dd56e0a78c09c5ba$::jsonb,true),'{features}',$text_61e38f752e2d89de$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Útiles de herborista. Este conjunto de objetos incluye una gran variedad de herramientas utilizadas por los herboristas para crear remedios y pociones, como pueden ser unas cizallas, un mortero, bolsas y viales. La competencia con estos útiles te permite sumar tu bonificador por competencia a las pruebas de característica que hagas para identificar o aplicar hierbas. Además, se necesita competencia con estos útiles para elaborar antitoxinas y pociones de curación.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_61e38f752e2d89de$::jsonb,true),'{rules,definition,description}',$text_60ab5a3c8c12bf60$[{"id":"official-table","rows":[["Útiles de herborista","5 po","3 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Útiles de herborista. Este conjunto de objetos incluye una gran variedad de herramientas utilizadas por los herboristas para crear remedios y pociones, como pueden ser unas cizallas, un mortero, bolsas y viales. La competencia con estos útiles te permite sumar tu bonificador por competencia a las pruebas de característica que hagas para identificar o aplicar hierbas. Además, se necesita competencia con estos útiles para elaborar antitoxinas y pociones de curación.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"tools-context-general","text":"Las herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-tools-context"],"provenance":"official-spanish"}]$text_60ab5a3c8c12bf60$::jsonb,true),'{catalog,revision}',$text_4b227777d4dd1fc6$4$text_4b227777d4dd1fc6$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_ee76d66ef5f1117d$["official-table","official-rules-0","tools-context-general"]$text_ee76d66ef5f1117d$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_9a5d864abfda580db6a8b26bcd25282a' and entity_id='inv_bdf552de3729a268a174a3df143ae4f0';

